import jax
import jax.numpy as jnp


def get_input_generator():
  def generate(key):
    k1, k2 = jax.random.split(key)
    a = jax.random.normal(k1, (1024, 1024), jnp.float32)
    b = jax.random.normal(k2, (1024, 1024), jnp.float32)
    return (a, b), {}
  return generate

